`timescale 1ns/1ps
// KV-RTRUNK 10-17: tb_qkd_pvw_die_t + the pair's 534-b RESULT STREAM rs_* (two result trunks -> header), in lockstep with
// the 16,384-b po: beat b must leave rs_* at pair age out_age + RS_D + b (b = 0..31, consecutive edges), carry beat index
// b and the command epoch, and its 512-b data must equal column b's y captured at that column's own y_valid (and the
// golden).  RS_MUT=1 (column 5 injects one edge late) must FAIL.  Line: PV_PAIR_RS PASS|FAIL.
// KVPLAN 1815: bench of the trunked PV16 pair successor qkd_pvw_die_t (generated by tools/qwen_kv_die/pv_trunk_gen.py)
// against the old pair's golden (tools/qwen_attention_native/rate_1015/pv_pair_ref.py, compare-only).  The boundary model
// is the old bench's: a request visible in cycle X on port k is answered RL edges later -- the 31-b header vh<k> at X + RL,
// e (in_e) with it, and every 128-b V chunk vc<k>_<g> DELTA[g] edges after it (the die relay chains are padded to that).
// Checks: every column s's 512-b y bit-exact at ITS y_valid edge, which must be the old static age shifted by the column's
// added depth (out_age + COL_D[s] - COL_D[0]), all 32 columns seen, no fault, out_age = column 0's age.
// Plusargs: +VEC=dir +CTX=T.  Parameters: TRUNK_MUT / FLAG_D_ADJ (negative controls, both must FAIL).
// KVJ-SMALL 10-17: RL is the boundary round trip (die: RL 95 -> FIRST_INPUT_AGE 96); AGE_ADJ builds the control tile at
// RL+1+AGE_ADJ (negative control: AGE_ADJ=-1 = the old age-95 view against an RL-95 boundary must FAIL).  Request queues
// are 256 deep (RL 95 keeps > 64 requests in flight per port).
module tb_qkd_pvw_die_t_rs;
 parameter integer PAIR=0, RL=19, AGE_ADJ=0, TRUNK_MUT=0, FLAG_D_ADJ=0, LEAF_RESET_PIN=1, CTL_RESET_PIN=1, RS_MUT=0;
 reg clk=0,rst_n=0;always #1 clk=~clk;
 reg start=0;integer CTX;string vec;
 reg [30:0] vh[0:7];reg [127:0] vc[0:7][0:7];reg [511:0] in_e=0;
 wire [14:0] vrq[0:7];wire out_valid,fault,busy;wire [16383:0] out_leaf;wire [15:0] out_epoch,out_age;
 wire rs_valid;wire [4:0] rs_beat;wire [15:0] rs_epoch;wire [511:0] rs_data;
 qkd_pvw_die_t #(.PAIR(PAIR),.CTL_RESET_PIN(CTL_RESET_PIN),.LEAF_RESET_PIN(LEAF_RESET_PIN),.FIRST_INPUT_AGE(RL+1+AGE_ADJ),
  .TRUNK_MUT(TRUNK_MUT),.FLAG_D_ADJ(FLAG_D_ADJ),.RS_MUT(RS_MUT)) u(.rst_n(rst_n),.start(start),.col_clk({33{clk}}),.context_len(14'(CTX)),.epoch(16'd23),
  .vh0(vh[0]),.vh1(vh[1]),.vh2(vh[2]),.vh3(vh[3]),.vh4(vh[4]),.vh5(vh[5]),.vh6(vh[6]),.vh7(vh[7]),
`include "tb_qkd_pvw_die_t_vc.svh"
  .in_e(in_e),.vrq0(vrq[0]),.vrq1(vrq[1]),.vrq2(vrq[2]),.vrq3(vrq[3]),.vrq4(vrq[4]),.vrq5(vrq[5]),.vrq6(vrq[6]),.vrq7(vrq[7]),
  .out_valid(out_valid),.out_leaf(out_leaf),.out_epoch(out_epoch),.fault(fault),.busy(busy),.out_age(out_age),
  .rs_valid(rs_valid),.rs_beat(rs_beat),.rs_epoch(rs_epoch),.rs_data(rs_data));
 reg [1023:0] vr[0:8191];reg [63:0] er[0:8191];reg [31:0] gold[0:511];
 integer due[0:7][0:255],tt[0:7][0:255],wp[0:7],rp[0:7];
 integer cyc=0,scyc=-1,errors=0,words=0,nreq=0,i,k,n,g,d,seen=0,agebad=0;
 integer ycyc[0:31];
 reg [511:0] yref[0:31];integer nbeat=0,rserr=0,rsfirst=-1;
 // per-port presentation pipeline: header now, chunk g after DELTA[g] edges
 reg [1023:0] vq[0:7][0:63];reg vqv[0:7][0:63];
 always @(posedge clk)cyc<=cyc+1;
 initial begin
  if(!$value$plusargs("VEC=%s",vec))$fatal(1,"+VEC");
  if(!$value$plusargs("CTX=%d",CTX))$fatal(1,"+CTX");
  for(i=0;i<3;i=i+1)begin
   n=$fopen({vec,(i==0)?"/v.hex":(i==1)?"/e.hex":"/gold.hex"},"r");
   if(n==0)$fatal(1,"missing vector file in %0s",vec);
   $fclose(n);
  end
  $readmemh({vec,"/v.hex"},vr);$readmemh({vec,"/e.hex"},er);$readmemh({vec,"/gold.hex"},gold);
  for(k=0;k<8;k=k+1)begin wp[k]=0;rp[k]=0;vh[k]=0;for(g=0;g<8;g=g+1)vc[k][g]=0;for(d=0;d<64;d=d+1)vqv[k][d]=0;end
  for(i=0;i<32;i=i+1)ycyc[i]=-1;
  repeat(5)@(negedge clk);rst_n=1;repeat(200)@(negedge clk);   // >= the deepest reset station chain
  start=1;scyc=cyc;@(negedge clk);start=0;
 end
 always @(negedge clk)if(rst_n)begin
  // V words due now: header (vh) + e now; chunk g lands DELTA[g] edges later
  for(k=0;k<8;k=k+1)begin
   vh[k]=0;
   for(d=63;d>0;d=d-1)begin vq[k][d]=vq[k][d-1];vqv[k][d]=vqv[k][d-1];end
   vqv[k][0]=0;vq[k][0]=0;
   if(rp[k]!=wp[k]&&due[k][rp[k]%256]==cyc)begin
    n=tt[k][rp[k]%256];rp[k]=rp[k]+1;
    vh[k]={16'd23,14'(n),1'b1};in_e[64*k+:64]=er[n];vq[k][0]=vr[n];vqv[k][0]=1;
   end
   for(g=0;g<8;g=g+1)vc[k][g]=vq[k][u.DELTA[8*g+:8]][128*g+:128];
  end
  #0.5;
  for(k=0;k<8;k=k+1)if(vrq[k][0])begin
   due[k][wp[k]%256]=cyc+RL;tt[k][wp[k]%256]=vrq[k][14:1];wp[k]=wp[k]+1;nreq=nreq+1;
  end
 end
 genvar s;
 generate for(s=0;s<32;s=s+1)begin:g_chk
  always @(posedge clk)if(rst_n&&u.yv_w[s])begin
   if(ycyc[s]>=0)begin errors=errors+1;$display("COLUMN %0d valid twice",s);end
   ycyc[s]=cyc;seen=seen+1;yref[s]=out_leaf[512*s+:512];
   for(i=0;i<16;i=i+1)begin
    if(out_leaf[512*s+32*i+:32]!==gold[16*s+i])begin if(errors<6)$display("MISMATCH col %0d w %0d got %08h want %08h",s,i,out_leaf[512*s+32*i+:32],gold[16*s+i]);errors=errors+1;end
    words=words+1;
   end
   if(cyc-scyc!=out_age+u.COL_D[8*s+:8]-u.COL_D[7:0])begin agebad=agebad+1;
    if(agebad<4)$display("AGE col %0d got %0d want %0d",s,cyc-scyc,out_age+u.COL_D[8*s+:8]-u.COL_D[7:0]);end
  end
 end endgenerate
 // the result stream: one beat per edge, beat b at out_age + RS_D + b, data = column b's y at its own y_valid
 always @(posedge clk)if(rst_n&&rs_valid)begin
  if(rsfirst<0)rsfirst=cyc-scyc;
  if(nbeat>31)begin rserr=rserr+1;if(rserr<6)$display("RS extra beat at age %0d",cyc-scyc);end
  else begin
   if(ycyc[nbeat]<0)begin rserr=rserr+1;if(rserr<6)$display("RS beat %0d before its column's y_valid",nbeat);end
   if(rs_beat!==5'(nbeat)||rs_epoch!==16'd23)begin rserr=rserr+1;if(rserr<6)$display("RS beat %0d header beat=%0d epoch=%0d",nbeat,rs_beat,rs_epoch);end
   if(cyc-scyc!=out_age+u.RS_D+nbeat)begin rserr=rserr+1;if(rserr<6)$display("RS beat %0d age %0d want %0d",nbeat,cyc-scyc,out_age+u.RS_D+nbeat);end
   if(rs_data!==yref[nbeat])begin rserr=rserr+1;if(rserr<6)$display("RS beat %0d data != column y (po)",nbeat);end
   for(i=0;i<16;i=i+1)if(rs_data[32*i+:32]!==gold[16*nbeat+i])begin rserr=rserr+1;if(rserr<6)$display("RS beat %0d w %0d got %08h want %08h",nbeat,i,rs_data[32*i+:32],gold[16*nbeat+i]);end
  end
  nbeat=nbeat+1;
 end
 initial begin
  #40000;
  $display("PV_PAIR_RS %s T=%0d beats=%0d rserr=%0d first_beat_age=%0d out_age=%0d rs_d=%0d rs_mut=%0d",
   (rserr==0&&nbeat==32&&errors==0&&words==512&&seen==32&&agebad==0&&!fault)?"PASS":"FAIL",CTX,nbeat,rserr,rsfirst,out_age,u.RS_D,RS_MUT);
  $display("PV_PAIR_T %s T=%0d pair=%0d words=%0d cols=%0d errors=%0d agebad=%0d fault=%0d out_age=%0d col0_age=%0d rows=%0d trunk_d=%0d flag_d=%0d rl=%0d first_input_age=%0d",
   (errors==0&&words==512&&seen==32&&agebad==0&&!fault)?"PASS":"FAIL",CTX,PAIR,words,seen,errors,agebad,fault,out_age,ycyc[0]-scyc,nreq,
   u.TRUNK_D,u.FLAG_D,RL,RL+1+AGE_ADJ);
  $finish;
 end
endmodule
